const statusBadge = document.querySelector("#connection-status");
const statusLabel = document.querySelector("#status-label");
const resultTitle = document.querySelector("#result-title");
const resultDetail = document.querySelector("#result-detail");
const responseOutput = document.querySelector("#response-output");
const checkButton = document.querySelector("#check-button");

/** Fetches the backend health endpoint and presents its current status. */
async function checkBackend() {
  checkButton.disabled = true;
  statusBadge.dataset.state = "checking";
  statusLabel.textContent = "Checking";
  resultTitle.textContent = "Connecting to backend";
  resultDetail.textContent = "Waiting for a response from the health endpoint.";
  responseOutput.textContent = "Request in progress...";

  try {
    const response = await fetch("http://127.0.0.1:3000/health", {
      headers: { Accept: "application/json" },
      cache: "no-store",
      signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) {
      throw new Error("Backend returned an unsuccessful response");
    }

    const payload = await response.json();
    if (payload.status !== "ok") {
      throw new Error("Backend health response is invalid");
    }

    statusBadge.dataset.state = "online";
    statusLabel.textContent = "Online";
    resultTitle.textContent = "Backend is responding";
    resultDetail.textContent = "The health check completed successfully.";
    responseOutput.textContent = JSON.stringify(payload, null, 2);
  } catch {
    statusBadge.dataset.state = "offline";
    statusLabel.textContent = "Offline";
    resultTitle.textContent = "Backend is unavailable";
    resultDetail.textContent = "Start the backend service and check again.";
    responseOutput.textContent = "No successful response received.";
  } finally {
    checkButton.disabled = false;
  }
}

checkButton.addEventListener("click", checkBackend);
checkBackend();